/**
 * Shared repo clone / edit / push for Nigents agents.
 * Fetches the plan's GitLab repo, applies generated files, pushes to the task's branch (plan.branch).
 */

const path = require('path');
const os = require('os');
const fs = require('fs-extra');
const simpleGit = require('simple-git');
const logger = require('../utils/logger');
const gitlab = require('./gitlab');
const { runCheckLocal } = require('./compile-check');

/**
 * Clone the GitLab repo for the plan, apply generated files, push to plan.branch (task branch).
 * @param {Object} plan - Plan with project, branch, title, description
 * @param {Array<{path: string, content: string}>} generatedFiles - Files to write
 * @param {Object} [reporter] - Optional reporter for progress
 * @returns {Promise<{success: boolean}>}
 */
async function cloneEditAndPush(plan, generatedFiles, reporter) {
  const project = plan.project || plan.projectId;
  const branch = plan.branch || `nigents/task-${Date.now()}`;
  if (!project || !generatedFiles || generatedFiles.length === 0) {
    return { success: false };
  }
  const workDir = path.join(os.tmpdir(), `nigents-repo-${String(project).replace(/\//g, '-')}-${Date.now()}`);
  try {
    if (reporter) await reporter.sendProgress(`📂 Fetching repo from GitLab (pushing to branch \`${branch}\`)...`);
    const pushUrl = await gitlab.getPushUrl(project);
    const defaultBranch = await gitlab.getDefaultBranch(project);
    await fs.ensureDir(workDir);
    const git = simpleGit();
    await git.clone(pushUrl, workDir, ['--depth', '1', '--branch', defaultBranch]);
    let repoRoot = workDir;
    if (await fs.pathExists(path.join(workDir, '.git'))) {
      repoRoot = workDir;
    } else {
      const entries = await fs.readdir(workDir);
      const sub = entries.length === 1 ? path.join(workDir, entries[0]) : null;
      if (sub && (await fs.stat(sub).catch(() => null))?.isDirectory() && await fs.pathExists(path.join(sub, '.git'))) {
        repoRoot = sub;
      }
    }
    const gitRepo = simpleGit(repoRoot);
    await gitRepo.checkoutLocalBranch(branch);
    if (reporter) await reporter.sendProgress(`📝 Writing ${generatedFiles.length} file(s) in repo...`);
    for (const { path: filePath, content } of generatedFiles) {
      const fullPath = path.join(repoRoot, filePath);
      await fs.ensureDir(path.dirname(fullPath));
      await fs.writeFile(fullPath, content || '', 'utf8');
    }
    let compileCheckPassed = true;
    try {
      if (reporter) await reporter.sendProgress('🔍 Detecting project type and running compile/syntax check...');
      const checkResult = await runCheckLocal(repoRoot);
      if (!checkResult.success) {
        compileCheckPassed = false;
        logger.warn('[repo-clone-push] Compile check failed:', checkResult.error || checkResult.stderr?.slice(0, 200));
      }
    } catch (e) {
      compileCheckPassed = false;
      logger.warn('[repo-clone-push] Compile check error:', e.message);
    }
    const commitMessage = `feat: ${plan.title || 'Task'}\n\n${(plan.description || '').trim()}\n\nGenerated by Nigents`;
    await gitRepo.add('.');
    await gitRepo.commit(commitMessage);
    if (reporter) await reporter.sendProgress(`📤 Pushing branch \`${branch}\` to GitLab...`);
    await gitRepo.push('origin', branch);
    logger.info('[repo-clone-push] Pushed to branch:', branch);
    return { success: true, compileCheckPassed };
  } catch (err) {
    logger.error('[repo-clone-push] Failed:', err.message);
    throw err;
  } finally {
    await fs.remove(workDir).catch(() => {});
  }
}

module.exports = { cloneEditAndPush };
